package com.google.gson.internal;

import java.io.*;
import java.io.ObjectInputStream;
import java.io.ObjectStreamClass;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class UnsafeAllocator_create_TriageGen0Test {

    @Test
    public void testCreateReturnsInstanceOfUnsafeAllocator() {
        UnsafeAllocator allocator = UnsafeAllocator.create();
        assertNotNull("Allocator should not be null", allocator);
        assertTrue("Allocator should be an instance of UnsafeAllocator", allocator instanceof UnsafeAllocator);
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testCreateThrowsUnsupportedOperationExceptionWhenUnsafeNotAvailable() throws Exception {
        // Simulate the absence of sun.misc.Unsafe by temporarily modifying the method
        UnsafeAllocator originalMethod = UnsafeAllocator.create;
        UnsafeAllocator customCreate = () -> {
            try {
                Class<?> unsafeClass = Class.forName("sun.misc.Unsafe");
                return UnsafeAllocator.create();
            } catch (ClassNotFoundException e) {
                return new UnsafeAllocator() {
                    @Override
                    public <T> T newInstance(Class<T> c) {
                        throw new UnsupportedOperationException("Cannot allocate " + c);
                    }
                };
            }
        };

        try {
            UnsafeAllocator.create = customCreate;
            UnsafeAllocator allocator = UnsafeAllocator.create();
            allocator.newInstance(String.class);
        } finally {
            UnsafeAllocator.create = originalMethod;
        }
    }

    @Test
    public void testCreateUsesObjectStreamClassOnDalvikVMPostGingerbread() throws Exception {
        UnsafeAllocator allocator = UnsafeAllocator.create();
        assertNotNull("Allocator should not be null", allocator);

        try {
            Class<?> unsafeClass = Class.forName("sun.misc.Unsafe");
            ObjectStreamClass.class.getDeclaredMethod("getConstructorId", Class.class);
            assertTrue("Allocator should use ObjectStreamClass", allocator instanceof UnsafeAllocator);
        } catch (ClassNotFoundException e) {
            // Expected, as we are simulating a Dalvik VM environment
        }
    }

    @Test
    public void testCreateUsesObjectInputStreamOnDalvikVMPreGingerbread() throws Exception {
        UnsafeAllocator allocator = UnsafeAllocator.create();
        assertNotNull("Allocator should not be null", allocator);

        try {
            ObjectStreamClass.class.getDeclaredMethod("getConstructorId", Class.class);
            Class<?> objectInputStream = Class.forName("java.io.ObjectInputStream");
            objectInputStream.getDeclaredMethod("newInstance", Class.class, Class.class);
            assertTrue("Allocator should use ObjectInputStream", allocator instanceof UnsafeAllocator);
        } catch (ClassNotFoundException e) {
            // Expected, as we are simulating a pre-Gingerbread Dalvik VM environment
        }
    }

    @Test
    public void testNewInstanceCreatesInstanceSuccessfully() throws Exception {
        UnsafeAllocator allocator = UnsafeAllocator.create();
        assertNotNull("Allocator should not be null", allocator);

        String instance = allocator.newInstance(String.class);
        assertNotNull("Instance should not be null", instance);
        assertTrue("Instance should be of type String", instance instanceof String);
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testNewInstanceThrowsUnsupportedOperationExceptionWhenAllocationFails() throws Exception {
        UnsafeAllocator allocator = new UnsafeAllocator() {
            @Override
            public <T> T newInstance(Class<T> c) {
                throw new UnsupportedOperationException("Cannot allocate " + c);
            }
        };

        allocator.newInstance(String.class);
    }
}
